import java.io.*;
import java.util.*;

public class Main {
    private static final long MOD = 998244353L;
    private static long[] fact;

    public static void main(String[] args) {
        FastInput in = new FastInput();
        FastOutput out = new FastOutput(System.out);

        int t = 1;
        while (t-- > 0) {
            int n = in.nextInt();
            long k = in.nextLong();

            fact = new long[n + 1];
            fact[0] = fact[1] = 1L;
            for (int i = 2; i <= n; i++) {
                fact[i] = (fact[i - 1] * i) % MOD;
            }

            if (k == 0) {
                out.println(fact[n]);
            } else if (k >= n) {
                out.println(0);
            } else {
                int kVal = (int) k;
                long sum = 0L;
                long sign = 1L;
                int l = n - kVal;

                for (int i = 0; i <= l; i++) {
                    long term = pow(l - i, n, MOD);
                    term = (term * binomial(l, l - i)) % MOD;
                    term = (term * sign) % MOD;
                    sum = (sum + term + MOD) % MOD;
                    sign = -sign;
                }

                long ans = (2L * binomial(n, kVal) % MOD) * sum % MOD;
                out.println(ans);
            }
        }
        out.flush();
    }

    private static long binomial(int n, int r) {
        if (r < 0 || r > n) return 0L;
        if (r == 0 || r == n) return 1L;
        long denom = (fact[r] * fact[n - r]) % MOD;
        return (fact[n] * modInverse(denom, MOD)) % MOD;
    }

    private static long modInverse(long a, long mod) {
        return pow(a, mod - 2, mod);
    }

    private static long pow(long base, long exp, long mod) {
        long res = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    private static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    private static long solve(long x, long[] arr) {
        int n = arr.length;
        long q = x / n;
        int r = (int) (x % n);
        return arr[n - 1] * q + arr[r];
    }

    static class FastInput {
        private final InputStream is;
        private byte[] buffer = new byte[1 << 16];
        private int bufferLen = 0;
        private int index = 0;

        public FastInput(InputStream is) {
            this.is = is;
        }

        public FastInput() {
            this(System.in);
        }

        private int read() {
            if (index >= bufferLen) {
                try {
                    bufferLen = is.read(buffer);
                    index = 0;
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (bufferLen <= 0) return -1;
            }
            return buffer[index++];
        }

        private int skip() {
            int c;
            while ((c = read()) <= 32 && c != -1);
            return c;
        }

        public int nextInt() {
            int c = skip();
            if (c == -1) throw new RuntimeException("Input end");
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > 32) {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        public long nextLong() {
            int c = skip();
            if (c == -1) throw new RuntimeException("Input end");
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > 32) {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }

    static class FastOutput {
        private final BufferedOutputStream os;
        private final byte[] buf = new byte[1 << 16];
        private int pos = 0;

        public FastOutput(OutputStream os) {
            this.os = new BufferedOutputStream(os);
        }

        public void printLine(long x) {
            if (x == 0) {
                print('0');
            } else {
                if (x < 0) {
                    print('-');
                    x = -x;
                }
                char[] digits = new char[20];
                int len = 0;
                while (x > 0) {
                    digits[len++] = (char) ('0' + x % 10);
                    x /= 10;
                }
                for (int i = len - 1; i >= 0; i--) {
                    print(digits[i]);
                }
            }
            print('\n');
        }

        private void print(char c) {
            if (pos >= buf.length) {
                flush();
            }
            buf[pos++] = c;
        }

        public void flush() {
            try {
                os.write(buf, 0, pos);
                os.flush();
                pos = 0;
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}
